#!/usr/bin/env python3
"""
installer_paiement_v2.py — Installe paiement.py v2 SANS dependre d'un
second telechargement (le fichier est embarque ici en base64).

Ce qu'il fait :
  1. Sauvegarde l'actuel app/api/paiement.py en .bak-<horodatage>
  2. Ecrit la v2 (services a la carte, devise par pays, boutique)
  3. Purge app/api/__pycache__ (bytecode perime)
  4. PREUVE : importe le module comme Streamlit le fera et affiche
     le chemin charge + les attributs attendus
  5. Scanne les doublons paiement*.py qui pourraient faire de l'ombre

Retour arriere : python scripts/installer_paiement_v2.py --restaurer
"""
import ast
import base64
import shutil
import sys
from datetime import datetime
from pathlib import Path

RACINE = Path(__file__).resolve().parent.parent
CIBLE = RACINE / "app" / "api" / "paiement.py"

PAYLOAD = ""


def restaurer():
    baks = sorted(CIBLE.parent.glob("paiement.py.bak-*"))
    if not baks:
        print("Aucune sauvegarde paiement.py.bak-*")
        sys.exit(1)
    shutil.copy2(baks[-1], CIBLE)
    print(f"restaure depuis {baks[-1].name}")


def main():
    if "--restaurer" in sys.argv:
        restaurer(); return

    contenu = base64.b64decode(PAYLOAD)
    ast.parse(contenu.decode("utf-8"))          # jamais ecrire du casse

    if CIBLE.exists():
        if CIBLE.read_bytes() == contenu:
            print("= paiement.py : deja la v2")
        else:
            bak = CIBLE.with_suffix(f".py.bak-{datetime.now():%Y%m%d-%H%M%S}")
            shutil.copy2(CIBLE, bak)
            CIBLE.write_bytes(contenu)
            print(f"v paiement.py : v2 ecrite ({bak.name})")
    else:
        CIBLE.write_bytes(contenu)
        print("v paiement.py : v2 ecrite (aucun fichier precedent)")

    # cache bytecode
    pc = CIBLE.parent / "__pycache__"
    n = 0
    if pc.exists():
        for f in pc.glob("paiement*.pyc"):
            f.unlink(); n += 1
    print(f"v __pycache__ : {n} fichier(s) purge(s)")

    # PREUVE d'import, chemin compris
    sys.path.insert(0, str(CIBLE.parent))
    import importlib
    if "paiement" in sys.modules:
        del sys.modules["paiement"]
    import paiement
    print(f"\nPREUVE — module charge depuis : {paiement.__file__}")
    attendus = ["enregistrer_services", "ecran_boutique",
                "devise_cinetpay", "livrer_service", "duree_jours"]
    ok = True
    for a in attendus:
        present = hasattr(paiement, a)
        ok &= present
        print(f"  {'OK ' if present else 'MANQUE'} {a}")
    print(f"  mode : {paiement.MODE}")

    # doublons suspects
    doublons = [p for p in RACINE.rglob("paiement*.py")
                if ".venv" not in p.parts and "bak" not in p.name
                and p.resolve() != CIBLE.resolve()]
    if doublons:
        print("\n!! Doublons detectes (risque d'ombre a l'import) :")
        for d in doublons:
            print("   -", d.relative_to(RACINE))
    if not ok:
        print("\nECHEC : attributs manquants malgre l'ecriture — envoie cette sortie.")
        sys.exit(1)
    print("\nFINI. Relance : pkill -f streamlit ; streamlit run app/api/ui.py")


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        pass
